<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:12px}h1{font-size:26px;margin:0}h2{font-size:16px}.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{padding:10px;border-bottom:1px solid #dbe3ef;text-align:left}.right{text-align:right}.total{font-size:16px;font-weight:bold}</style></head><body><h1>StayTrack</h1><p class="muted">Apartment Management · Invoice #{{ $bill->id }}</p><table><tr><td><strong>Tenant</strong><br>{{ $bill->lease->tenant->full_name }}</td><td><strong>Apartment</strong><br>Unit {{ $bill->lease->apartment->unit_number }}</td></tr><tr><td><strong>Billing period</strong><br>{{ $bill->billing_month?->format('F Y') }}</td><td><strong>Due date</strong><br>{{ $bill->due_date?->format('M d, Y') }}</td></tr></table><table><thead><tr><th>Description</th><th class="right">Amount</th></tr></thead><tbody><tr><td>Monthly rent</td><td class="right">₱{{ number_format($bill->amount, 2) }}</td></tr><tr><td>Other charges / late fee</td><td class="right">₱{{ number_format($bill->late_fee, 2) }}</td></tr><tr class="total"><td>Total</td><td class="right">₱{{ number_format($bill->total_amount, 2) }}</td></tr><tr><td>Verified payments</td><td class="right">₱{{ number_format($paid, 2) }}</td></tr><tr class="total"><td>Remaining balance</td><td class="right">₱{{ number_format($balance, 2) }}</td></tr></tbody></table><p><strong>Status:</strong> {{ ucfirst(str_replace('_', ' ', $bill->status)) }}</p></body></html>
